const CHAVE_INICIATIVAS_SALVAS="casa-do-caminho:iniciativas-salvas:v1";function carregarIniciativasSalvas(){try{const texto=localStorage.getItem(CHAVE_INICIATIVAS_SALVAS),dados=texto?JSON.parse(texto):[];return Array.isArray(dados)?dados.filter(id=>"doacoes"===id||"voluntariado"===id):[]}catch(erro){return[]}}function gravarIniciativasSalvas(ids){try{return localStorage.setItem(CHAVE_INICIATIVAS_SALVAS,JSON.stringify(ids)),!0}catch(erro){return!1}}